class Solution {
    public int strictMajority(int[] votes) {
        int n = votes.length;
        for (int x : votes) {
            int c = 0;
            for (int y : votes) if (y == x) c++;
            if (c * 2 > n) return x;
        }
        return -1;
    }
}

