class Solution:
    def strictMajority(self, votes: List[int]) -> int:
        candidate, count = -1, 0
        for x in votes:
            if count == 0:
                candidate = x
            count += 1 if x == candidate else -1
        support = sum(1 for x in votes if x == candidate)
        return candidate if support * 2 > len(votes) else -1

