class Solution {
    public int strictMajority(int[] votes) {
        int candidate = -1, count = 0;
        for (int x : votes) {
            if (count == 0) candidate = x;
            count += (x == candidate) ? 1 : -1;
        }
        int support = 0;
        for (int x : votes) if (x == candidate) support++;
        return support * 2 > votes.length ? candidate : -1;
    }
}

