int strictMajority(int* votes, int votesSize) {
    int candidate = -1, count = 0;
    for (int i = 0; i < votesSize; i++) {
        if (count == 0) candidate = votes[i];
        count += (votes[i] == candidate) ? 1 : -1;
    }
    int support = 0;
    for (int i = 0; i < votesSize; i++) if (votes[i] == candidate) support++;
    return support * 2 > votesSize ? candidate : -1;
